(() => {
  const {e,icon,money}=window.UI,{t,content}=window.I18N;
  const {normalizeSearch}=window.PosTools;
  const menu=new window.DemoTools.MenuEngine(window.MADDAR_DEMOS.menu);
  const inventory=new window.DemoTools.InventoryEngine(window.MADDAR_DEMOS.inventory);
  const state={menuQuery:'',menuCategory:'all',stockQuery:'',stockLow:false,stockForm:{product:'SKU-101',direction:'in',amount:'1',note:''}};
  const local=value=>Array.isArray(value)?value[window.I18N.language==='en'?1:0]:value;
  const count=n=>n.toLocaleString(window.I18N.locale);
  const links=[{id:'pos',path:'/demo',icon:'pos',title:'posDemoTitle',description:'posDemoDesc'},{id:'menu',path:'/demos/menu',icon:'utensils',title:'menuDemoTitle',description:'menuDemoDesc'},{id:'inventory',path:'/demos/inventory',icon:'box',title:'inventoryDemoTitle',description:'inventoryDemoDesc'}];
  function nav(active){return '<nav class="demo-switcher" aria-label="'+e(t('demoHub'))+'"><a href="#/demos">'+t('allDemos')+'</a>'+links.map(d=>'<a href="#'+d.path+'" '+(d.id===active?'aria-current="page"':'')+'>'+icon(d.icon)+t(d.title)+'</a>').join('')+'</nav>';}
  function preview(id){
    if(id==='pos')return '<div class="sample-art sample-pos"><span class="sample-art-label">'+t('sampleLabel')+'</span><div class="mini-till"><span>'+icon('receipt')+'</span><i></i><i></i><i></i><b>'+money(17500)+'</b></div><div class="mini-art-note">'+icon('check')+t('posDemoTitle')+'</div></div>';
    if(id==='menu')return '<div class="sample-art sample-menu"><span class="sample-art-label">'+t('sampleLabel')+'</span><div class="mini-menu-scene">'+foodArt('coffee')+'<b>'+t('menuPreview')+'</b></div></div>';
    return '<div class="sample-art sample-stock"><span class="sample-art-label">'+t('sampleLabel')+'</span><div class="mini-stock-scene">'+icon('box')+'<b>'+t('inventoryPreview')+'</b><div><i style="--bar:70%"></i><i style="--bar:30%"></i><i style="--bar:90%"></i></div></div></div>';
  }
  function cards(){return '<div class="experience-cards">'+links.map(d=>'<a class="experience-card" href="#'+d.path+'">'+preview(d.id)+'<div class="experience-card-copy"><h3>'+t(d.title)+'</h3><p>'+t(d.description)+'</p><span>'+t('tryDemo')+' '+icon('arrow')+'</span></div></a>').join('')+'</div>';}
  function section(){return '<section class="examples-section section" id="examples"><div class="container"><div class="section-heading"><div><span class="eyebrow"><span class="section-number">03</span>'+t('sampleLabel')+'</span><h2>'+t('examples')+'</h2></div><p>'+t('examplesIntro')+'</p></div>'+cards()+'</div></section>';}
  function faq(){return '<section class="faq-section section" id="faq"><div class="container faq-layout"><div><span class="eyebrow">'+t('faqKicker')+'</span><h2>'+t('faqTitle')+'</h2><p>'+t('faqIntro')+'</p><a href="#/contact" class="text-link">'+t('discuss')+' '+icon('arrow')+'</a></div><div class="faq-list">'+window.MADDAR_FAQ.map(item=>'<details><summary>'+e(local(item.q))+icon('plus')+'</summary><p>'+e(local(item.a))+'</p></details>').join('')+'</div></div></section>';}
  function hub(){return '<main id="main" class="experience-main"><section class="section"><div class="container"><span class="eyebrow">'+t('sampleOnly')+'</span><h1>'+t('demoHub')+'</h1><p class="experience-intro">'+t('demoHubIntro')+'</p>'+cards()+'</div></section>'+custom('web')+faq()+'</main>';}
  function custom(service){return '<section class="experience-cta"><div class="container"><div><h2>'+t('demoCustom')+'</h2><p>'+t('demoCustomDesc')+'</p></div><a class="button button-orange" href="#/contact?service='+service+'">'+t('discuss')+' '+icon('arrow')+'</a></div></section>';}
  function demoHeader(id,title,description){return '<main id="main" class="experience-main"><div class="container">'+nav(id)+'<div class="experience-heading"><div><span class="eyebrow">'+t('sampleLabel')+'</span><h1>'+t(title)+'</h1><p>'+t(description)+'</p></div><button class="button button-outline" data-sample-reset>'+icon('refresh')+t('reset')+'</button></div><div class="experience-notice">'+icon('info')+'<p>'+t('demoBrowserNote')+'</p></div><p class="demo-status" role="status" aria-live="polite" id="demo-status"></p>';}
  function foodArt(kind){
    const drawings={
      burger:'<path d="M28 65c0-37 84-37 84 0Z" fill="#edb064"/><path d="M29 75h82M31 91h78" stroke="#714131" stroke-width="12" stroke-linecap="round"/><path d="m29 79 16 5 17-5 17 5 30-6" stroke="#7d9d68" stroke-width="7"/><path d="M28 99h84v9H28z" fill="#edb064"/><g fill="#fff0ce"><ellipse cx="48" cy="51" rx="3" ry="2"/><ellipse cx="71" cy="45" rx="3" ry="2"/><ellipse cx="91" cy="53" rx="3" ry="2"/></g>',
      coffee:'<path d="M40 50h55v45q-27 24-55 0Z" fill="#f2d7b9"/><path d="M95 58c29-5 27 36 0 31" fill="none" stroke="#f2d7b9" stroke-width="8"/><ellipse cx="67" cy="50" rx="27" ry="7" fill="#704b3e"/><path d="M55 34q-9-9 1-17m23 17q-9-9 1-17" fill="none" stroke="#d8bda7" stroke-width="4" stroke-linecap="round"/><path d="M32 113h73" stroke="#d8bda7" stroke-width="5" stroke-linecap="round"/>',
      pasta:'<ellipse cx="70" cy="83" rx="52" ry="27" fill="#faf2df"/><ellipse cx="70" cy="79" rx="39" ry="17" fill="#e6b96e"/><path d="M39 72q31-26 61 6M40 83q34-21 58 2M51 60q2 23 33 31" fill="none" stroke="#f7d595" stroke-width="6"/><path d="m59 65 11-5 9 8-14 5Z" fill="#7c9a5d"/>',
      drink:'<path d="m43 40 7 72h42l7-72Z" fill="#d8e2a9"/><path d="m72 57 17-42" stroke="#f4ede0" stroke-width="5"/><path d="m48 75 44-10M51 90l40-9" stroke="#f5f1c9" stroke-width="6"/><circle cx="46" cy="45" r="17" fill="#c6d36e"/><circle cx="46" cy="45" r="12" fill="#edf0b2"/><path d="M79 61q-8-25-19-16 1 17 19 16" fill="#6c9565"/>',
      cake:'<path d="m32 72 71-31 9 66H32Z" fill="#f3e7c6"/><path d="m32 72 71-31 5 15-76 30Z" fill="#c86b6b"/><path d="M32 105h80v9H32Z" fill="#a87f62"/><circle cx="83" cy="51" r="9" fill="#d34f52"/><path d="m81 43 7-9" stroke="#6b8a58" stroke-width="5"/>',
      brownie:'<path d="m32 57 30-20 49 19v51l-30 12-49-18Z" fill="#745144"/><path d="m32 57 49 17 30-18-49-19Z" fill="#a47a61"/><path d="M81 74v45" stroke="#4d352f" stroke-width="3"/><path d="m46 55 10-3m16 8 10-3m-9-11 9 3" stroke="#563e35" stroke-width="5"/>'
    };
    return '<svg viewBox="0 0 140 140" class="food-art" aria-hidden="true">'+drawings[kind]+'</svg>';
  }
  function menuItems(){
    const found=menu.items.filter(item=>(state.menuCategory==='all'||item.category===state.menuCategory)&&normalizeSearch(local(item.name)).includes(normalizeSearch(state.menuQuery)));
    return found.length?found.map(item=>'<article class="menu-dish '+(!item.available?'dish-unavailable':'')+'"><div class="dish-picture dish-'+item.art+'">'+foodArt(item.art)+'</div><div class="dish-info"><h3>'+e(local(item.name))+'</h3><p>'+e(local(item.description))+'</p><div><b>'+money(item.price)+'</b><button class="dish-add" data-menu-add="'+item.id+'" aria-label="'+e(t('menuAdd',{name:local(item.name)}))+'" '+(!item.available?'disabled':'')+'>'+icon('plus')+'</button></div>'+(!item.available?'<small>'+t('menuUnavailable')+'</small>':'')+'</div></article>').join(''):'<p class="sample-empty">'+t('demoNoResults')+'</p>';
  }
  function order(){return '<h2>'+icon('receipt')+t('menuOrder')+' <span>'+count(menu.count)+'</span></h2><div class="menu-lines">'+(menu.lines.length?menu.lines.map(item=>'<div class="menu-order-line"><div><b>'+e(local(item.name))+'</b><span>'+money(item.total)+'</span></div><div class="sample-quantity"><button data-menu-decrease="'+item.id+'" aria-label="'+e(t('decrease',{name:local(item.name)}))+'">'+icon('minus')+'</button><input type="number" inputmode="numeric" min="1" max="20" value="'+item.quantity+'" data-menu-quantity="'+item.id+'" aria-label="'+e(t('quantity',{name:local(item.name)}))+'"><button data-menu-add="'+item.id+'" '+(item.quantity>=20?'disabled':'')+' aria-label="'+e(t('increase',{name:local(item.name)}))+'">'+icon('plus')+'</button><button class="sample-remove" data-menu-remove="'+item.id+'" aria-label="'+e(t('removeProduct',{name:local(item.name)}))+'">'+icon('trash')+'</button></div></div>').join(''):'<div class="sample-empty">'+icon('utensils')+'<p>'+t('menuEmpty')+'</p></div>')+'</div><div class="menu-grand-total"><span>'+t('total')+'</span><b>'+money(menu.total)+'</b></div><button class="button button-orange" data-menu-summary '+(!menu.count?'disabled':'')+'>'+t('menuSummary')+'</button><small class="sample-order-note">'+t('sampleOnly')+'</small>';}
  function menuPage(){return demoHeader('menu','menuDemoTitle','menuDemoDesc')+'<div class="menu-layout"><section class="menu-catalog"><div class="menu-venue"><span>'+icon('utensils')+'</span><div><h2>'+t('menuVenue')+'</h2><p>'+t('menuVenueSub')+'</p></div><span class="venue-mark" aria-hidden="true">H.</span></div><div class="sample-search">'+icon('search')+'<input id="menu-search" type="search" value="'+e(state.menuQuery)+'" placeholder="'+e(t('menuSearch'))+'" aria-label="'+e(t('menuSearch'))+'"></div><div class="sample-filters" aria-label="'+e(t('menuDemoTitle'))+'">'+['all','main','drinks','desserts'].map(id=>'<button data-menu-category="'+id+'" aria-pressed="'+(id===state.menuCategory)+'">'+t({all:'menuAll',main:'menuMain',drinks:'menuDrinks',desserts:'menuDesserts'}[id])+'</button>').join('')+'</div><div id="menu-items" class="menu-dishes">'+menuItems()+'</div></section><aside class="menu-order" id="menu-order" aria-label="'+e(t('menuOrder'))+'">'+order()+'</aside></div></div>'+custom('menu')+'</main>';}
  function stockStats(){return [[inventory.products.length,'inventoryKinds'],[inventory.products.reduce((sum,p)=>sum+p.stock,0),'inventoryUnits'],[inventory.products.filter(p=>p.stock<=p.minimum).length,'inventoryAlerts']].map(([value,key])=>'<div><span>'+t(key)+'</span><b>'+count(value)+'</b></div>').join('');}
  function stockRows(){
    const q=normalizeSearch(state.stockQuery),products=inventory.products.filter(p=>(!state.stockLow||p.stock<=p.minimum)&&(normalizeSearch(local(p.name)).includes(q)||normalizeSearch(p.id).includes(q)));
    return products.length?products.map(p=>'<tr data-stock-id="'+p.id+'"><td><b>'+e(local(p.name))+'</b><small dir="ltr">'+p.id+'</small></td><td class="stock-number">'+count(p.stock)+'</td><td>'+count(p.minimum)+'</td><td><span class="stock-badge '+(p.stock===0?'empty':p.stock<=p.minimum?'low':'okay')+'">'+t(p.stock===0?'stockOut':p.stock<=p.minimum?'stockLow':'stockOkay')+'</span></td><td><button class="stock-row-action" data-stock-select="'+p.id+'">'+t('stockMove')+icon('plus')+'</button></td></tr>').join(''):'<tr><td colspan="5" class="sample-empty">'+t('demoNoResults')+'</td></tr>';
  }
  function history(){return inventory.movements.length?inventory.movements.slice(0,8).map(m=>'<li><span class="movement-direction '+m.type+'">'+(m.type==='in'?'+':'−')+count(m.quantity)+'</span><div><b>'+e(local(inventory.products.find(p=>p.id===m.productId).name))+'</b><small>'+t(m.type==='in'?'stockIn':'stockOutAction')+' · '+t('stockBalance')+' '+count(m.balance)+(m.note?' · '+e(m.note):'')+'</small></div><time datetime="'+new Date(m.time).toISOString()+'">'+new Intl.DateTimeFormat(window.I18N.locale,{hour:'2-digit',minute:'2-digit'}).format(m.time)+'</time></li>').join(''):'<li class="sample-empty">'+t('stockHistoryEmpty')+'</li>';}
  function inventoryPage(){return demoHeader('inventory','inventoryHeading','inventorySub')+'<div class="stock-stats" id="stock-stats">'+stockStats()+'</div><div class="stock-layout"><section class="stock-catalog"><div class="stock-tools"><div class="sample-search">'+icon('search')+'<input id="stock-search" type="search" value="'+e(state.stockQuery)+'" aria-label="'+e(t('inventorySearch'))+'" placeholder="'+e(t('inventorySearch'))+'"></div><button data-stock-low class="stock-filter" aria-pressed="'+state.stockLow+'">'+icon('box')+t('inventoryLow')+'</button></div><div class="stock-table-wrap"><table class="stock-table"><caption class="sr-only">'+t('inventoryDemoTitle')+'</caption><thead><tr>'+['stockProduct','stockBalance','stockMinimum','stockStatus','stockMove'].map(key=>'<th scope="col">'+t(key)+'</th>').join('')+'</tr></thead><tbody id="stock-rows">'+stockRows()+'</tbody></table></div><p class="stock-scroll-hint">'+t('stockScrollHint')+'</p><button class="text-link stock-export" data-stock-export>'+icon('arrowup')+t('stockExport')+'</button></section><aside class="stock-form-panel"><h2>'+t('stockMovement')+'</h2><form id="stock-movement" novalidate><label for="stock-product">'+t('stockProduct')+'</label><select id="stock-product" name="product">'+inventory.products.map(p=>'<option value="'+p.id+'">'+e(local(p.name))+'</option>').join('')+'</select><label for="stock-direction">'+t('stockDirection')+'</label><select id="stock-direction" name="direction"><option value="in">'+t('stockIn')+'</option><option value="out">'+t('stockOutAction')+'</option></select><label for="stock-amount">'+t('stockAmount')+'</label><input id="stock-amount" name="amount" type="number" inputmode="numeric" min="1" max="9999" step="1" value="1" aria-describedby="stock-error" required><label for="stock-note">'+t('stockNote')+'</label><input id="stock-note" name="note" maxlength="120"><p id="stock-error" class="sample-error" role="alert"></p><button class="button button-orange">'+t('stockSave')+'</button></form></aside></div><section class="stock-history"><h2>'+t('stockHistory')+'</h2><ul id="stock-history">'+history()+'</ul></section></div>'+custom('pos')+'</main>';}
  function privacy(){return '<main id="main" class="privacy-page container section"><span class="eyebrow">Maddar Digital</span><h1>'+t('privacyTitle')+'</h1><p>'+t('privacyIntro')+'</p><p>'+t('privacyBody')+'</p><a class="text-link" href="#/contact">'+t('contact')+icon('arrow')+'</a></main>';}
  function bind(route,notify){
    if(!['menuDemo','inventoryDemo'].includes(route))return;
    const root=document.getElementById('main');
    const status=message=>{document.getElementById('demo-status').textContent=message;};
    const refreshMenu=()=>{document.getElementById('menu-items').innerHTML=menuItems();document.getElementById('menu-order').innerHTML=order();};
    const refreshStock=()=>{document.getElementById('stock-stats').innerHTML=stockStats();document.getElementById('stock-rows').innerHTML=stockRows();document.getElementById('stock-history').innerHTML=history();};
    root.querySelector('[data-sample-reset]').addEventListener('click',()=>{
      if(route==='menuDemo'){menu.reset();state.menuQuery='';state.menuCategory='all';root.querySelector('#menu-search').value='';root.querySelectorAll('[data-menu-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.menuCategory==='all'));refreshMenu();}
      else{inventory.reset();state.stockQuery='';state.stockLow=false;state.stockForm={product:'SKU-101',direction:'in',amount:'1',note:''};root.querySelector('#stock-search').value='';root.querySelector('[data-stock-low]').setAttribute('aria-pressed','false');root.querySelector('#stock-movement').reset();root.querySelector('#stock-error').textContent='';root.querySelector('#stock-amount').removeAttribute('aria-invalid');refreshStock();}status(t('resetSuccess'));
    });
    if(route==='menuDemo'){
      root.querySelector('#menu-search').addEventListener('input',ev=>{state.menuQuery=ev.target.value;document.getElementById('menu-items').innerHTML=menuItems();});
      root.addEventListener('click',ev=>{
        const button=ev.target.closest('button');if(!button)return;
        const {menuCategory,menuAdd,menuRemove,menuDecrease}=button.dataset;
        if(menuCategory){state.menuCategory=menuCategory;root.querySelectorAll('[data-menu-category]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.getElementById('menu-items').innerHTML=menuItems();return;}
        try{
          if(menuAdd)menu.add(menuAdd);
          if(menuRemove)menu.remove(menuRemove);
          if(menuDecrease){const n=menu.cart.get(menuDecrease);if(n===1)menu.remove(menuDecrease);else menu.set(menuDecrease,n-1);}
          if(menuAdd||menuRemove||menuDecrease){status('');refreshMenu();root.querySelector('[data-menu-add="'+(menuAdd||menuDecrease||menuRemove)+'"]')?.focus({preventScroll:true});}
          if(button.hasAttribute('data-menu-summary')&&menu.count){
            const dialog=document.getElementById('sample-dialog');
            dialog.innerHTML='<button class="dialog-close" aria-label="'+e(t('closeSample'))+'">'+icon('close')+'</button><span class="eyebrow">'+t('sampleLabel')+'</span><h2 id="sample-dialog-title">'+t('menuSummaryTitle')+'</h2><div class="receipt-lines">'+menu.lines.map(p=>'<div><span>'+e(local(p.name))+' × '+count(p.quantity)+'</span><b>'+money(p.total)+'</b></div>').join('')+'</div><div class="receipt-total"><span>'+t('total')+'</span><b>'+money(menu.total)+'</b></div><p class="sample-summary-note">'+t('menuSummaryNote')+'</p>';
            dialog.showModal();
          }
        }catch(error){status(t(error.code==='menuLimit'?'menuLimit':'sampleQuantity'));}
      });
      root.addEventListener('change',ev=>{const id=ev.target.dataset.menuQuantity;if(!id)return;try{menu.set(id,ev.target.value);status('');refreshMenu();}catch(error){ev.target.value=menu.cart.get(id);status(t(error.code==='menuLimit'?'menuLimit':'sampleQuantity'));}});
    }else{
      const stockForm=root.querySelector('#stock-movement');
      for(const [name,value]of Object.entries(state.stockForm))stockForm.elements[name].value=value;
      const captureStockForm=()=>{state.stockForm=Object.fromEntries(new FormData(stockForm));};
      stockForm.addEventListener('input',captureStockForm);stockForm.addEventListener('change',captureStockForm);
      root.querySelector('#stock-search').addEventListener('input',ev=>{state.stockQuery=ev.target.value;document.getElementById('stock-rows').innerHTML=stockRows();});
      root.querySelector('[data-stock-low]').addEventListener('click',ev=>{state.stockLow=!state.stockLow;ev.currentTarget.setAttribute('aria-pressed',state.stockLow);document.getElementById('stock-rows').innerHTML=stockRows();});
      root.addEventListener('click',ev=>{const button=ev.target.closest('[data-stock-select]');if(button){document.getElementById('stock-product').value=button.dataset.stockSelect;captureStockForm();document.getElementById('stock-amount').focus();}});
      root.querySelector('#stock-movement').addEventListener('submit',ev=>{
        ev.preventDefault();const form=ev.currentTarget,feedback=document.getElementById('stock-error');
        try{inventory.move(form.elements.product.value,form.elements.direction.value,form.elements.amount.value,form.elements.note.value);feedback.textContent='';form.elements.amount.removeAttribute('aria-invalid');form.elements.note.value='';captureStockForm();refreshStock();status(t('stockSaved'));}
        catch(error){feedback.textContent=error.code==='stock'?t('stockInsufficient',{count:count(error.stock)}):t('sampleQuantity');form.elements.amount.setAttribute('aria-invalid','true');form.elements.amount.focus();}
      });
      root.querySelector('[data-stock-export]').addEventListener('click',()=>{
        const csv='\uFEFF'+t('stockCsv')+'\r\n'+inventory.products.map(p=>[p.id,'"'+local(p.name).replaceAll('"','""')+'"',p.stock,p.minimum].join(',')).join('\r\n');
        const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='maddar-sample-inventory.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
      });
    }
  }
  const dialog=document.getElementById('sample-dialog');
  dialog.addEventListener('click',ev=>{if(ev.target===dialog||ev.target.closest('.dialog-close'))dialog.close();});
  window.Experiences={section,cards,faq,hub,menuPage,inventoryPage,nav,bind,privacy};
})();
